@rendermode InteractiveServer
@using RecipeShare.Models

<div class="my-3">
    <strong>Rate this recipe:</strong>
    <span class="ms-2" style="font-size: 1.5rem; cursor: pointer;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = 0"
                  class="@(GetStarClass(star))">
                @(IsStarFilled(star) ? "★" : "☆")
            </span>
        }
    </span>

    @if (rated)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }

    @if (RatingCount > 0)
    {
        <div class="text-muted mt-1">
            Average: @CurrentRating.ToString("F1") / 5 (@RatingCount ratings)
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int hoverStar;
    private bool rated;

    private bool IsStarFilled(int star)
    {
        if (hoverStar > 0) return star <= hoverStar;
        return star <= (int)Math.Round(CurrentRating);
    }

    private string GetStarClass(int star)
    {
        return IsStarFilled(star) ? "text-warning" : "text-secondary";
    }

    private void Rate(int stars)
    {
        RecipeStore.AddRating(RecipeId, stars);
        var recipe = RecipeStore.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        rated = true;
    }
}

